import { createContext, useContext, useState, useEffect } from "react";
import axios from "axios";
import { useAuth0 } from "@auth0/auth0-react";

const RecipesContext = createContext();

export function RecipesProvider({ children }) {
  const [recipes, setRecipes] = useState([]);
  const { isAuthenticated, user } = useAuth0();
  const API_URL = process.env.REACT_APP_API_URL;

  // Load from sessionStorage on first render
  useEffect(() => {
    const stored = sessionStorage.getItem("recipes");
  
    if (stored) {
      setRecipes(JSON.parse(stored));
    } else {
      fetchRecipes();
    }
  }, [user]);

  // Save to sessionStorage whenever recipes change
  useEffect(() => {
    sessionStorage.setItem("recipes", JSON.stringify(recipes));
  }, [recipes]);

  async function fetchRecipes() {
    if (!user) return;
    let strippedAuthId = removePrefix(user.sub, 'auth0|');

    let databaseUser = await axios.get(`${API_URL}/api/users/${strippedAuthId}`);

    const res = await axios.get(`${API_URL}/api/recipes/${databaseUser.data.id}`);
    setRecipes(res.data);
  }

  function removePrefix(str, prefix) {
    return str.startsWith(prefix)
      ? str.slice(prefix.length)
      : str;
  } 

  fetchRecipes()

  return (
    <RecipesContext.Provider value={{ recipes, setRecipes, fetchRecipes }}>
      {children}
    </RecipesContext.Provider>
  );
}

export function useRecipes() {
  return useContext(RecipesContext);
}
